document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("fertilizer-form"),n=document.getElementById("fertilizer-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("fertilizer-area").value),p=parseFloat(document.getElementById("fertilizer-plant-type").value),[i,r,a,s]=document.getElementById("fertilizer-npk").value.split(",").map(Number),l=parseFloat(document.getElementById("fertilizer-application").value);document.getElementById("fertilizer-form").value;if(t<=0)return n.textContent="Please enter a valid area.",void 0;const o=t/1e3*(p/l),d=o/(i/100),c=d*l,u=Math.ceil(d/50),g=Math.ceil(c/50),h=u*s,m=g*s,v=c*(i/100),y=c*(r/100),f=c*(a/100),$=d/(t/1e3);let b="";b=$<=2?"Setting 2-3 (light application)":$<=4?"Setting 3-4 (medium application)":"Setting 4-5 (heavy application)";const F={1:["Early spring (March-April)"],2:["Early spring (March-April)","Fall (September-October)"],3:["Early spring (March)","Late spring (May)","Fall (September)"],4:["Early spring (March)","Late spring (May)","Summer (July)","Fall (September)"]}[l]||[];n.innerHTML=`\n        <div class="result-section">\n          <h4>Fertilizer Requirements:</h4>\n          <p>Area: ${t.toLocaleString()} sq ft</p>\n          <p>Fertilizer: ${i}-${r}-${a}</p>\n          <p>Application schedule: ${l} times per year</p>\n          <p>Target nitrogen rate: ${p} lbs/1000 sq ft annually</p>\n        </div>\n        \n        <div class="result-application">\n          <h4>Per Application:</h4>\n          <p><strong>${d.toFixed(1)} lbs fertilizer needed</strong></p>\n          <p><strong>${u} bags</strong> (50 lb bags)</p>\n          <p>Nitrogen applied: ${o.toFixed(1)} lbs</p>\n          <p>Application rate: ${$.toFixed(1)} lbs per 1000 sq ft</p>\n          <p>Cost per application: $${h.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-annual">\n          <h4>Annual Totals:</h4>\n          <p><strong>${c.toFixed(1)} lbs fertilizer</strong></p>\n          <p><strong>${g} bags needed</strong></p>\n          <p>Total nitrogen: ${v.toFixed(1)} lbs</p>\n          <p>Total phosphorus: ${y.toFixed(1)} lbs</p>\n          <p>Total potassium: ${f.toFixed(1)} lbs</p>\n          <p><strong>Annual cost: $${m.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-timing">\n          <h4>Application Schedule:</h4>\n          ${F.map((e,n)=>`<p><strong>Application ${n+1}:</strong> ${e}</p>`).join("")}\n          <p>Wait 6-8 weeks between applications</p>\n          <p>Avoid application during drought or extreme heat</p>\n        </div>\n        \n        <div class="result-spreader">\n          <h4>Spreader Settings:</h4>\n          <p>${b}</p>\n          <p>Calibrate spreader before first use</p>\n          <p>Walk at steady 3 mph pace</p>\n          <p>Overlap patterns by 6 inches</p>\n          <p>Apply when grass is dry, soil is moist</p>\n        </div>\n        \n        <div class="result-nutrients">\n          <h4>Nutrient Analysis:</h4>\n          <p>Nitrogen: ${(v/t*1e3).toFixed(2)} lbs/1000 sq ft</p>\n          <p>Phosphorus: ${(y/t*1e3).toFixed(2)} lbs/1000 sq ft</p>\n          <p>Potassium: ${(f/t*1e3).toFixed(2)} lbs/1000 sq ft</p>\n          <p>NPK ratio maintained throughout year</p>\n        </div>\n        \n        <div class="result-application-tips">\n          <h4>Application Guidelines:</h4>\n          <p>🌡️ Apply when temperature is 60-80°F</p>\n          <p>💧 Water lightly after granular application</p>\n          <p>🌱 Avoid applying to wet grass</p>\n          <p>⏰ Apply in early morning or evening</p>\n          <p>🚫 Don't apply before heavy rain</p>\n        </div>\n        \n        <div class="result-safety">\n          <h4>Safety & Environment:</h4>\n          <p>🧤 Wear gloves and avoid skin contact</p>\n          <p>💧 Don't apply near water sources</p>\n          <p>🌬️ Avoid windy conditions</p>\n          <p>🏠 Keep children and pets off treated areas</p>\n          <p>♻️ Dispose of empty bags properly</p>\n        </div>\n        \n        <div class="result-alternatives">\n          <h4>Cost Comparison:</h4>\n          <p>Current plan: $${m.toFixed(0)}/year</p>\n          <p>Organic alternative: $${(1.5*m).toFixed(0)}/year (50% more)</p>\n          <p>Professional service: $${(.15*t).toFixed(0)}/year ($0.15/sq ft)</p>\n          <p>Cost per sq ft: $${(m/t).toFixed(3)}</p>\n        </div>\n        \n        <div class="result-storage">\n          <h4>Storage & Handling:</h4>\n          <p>📦 Store in cool, dry location</p>\n          <p>🛡️ Keep in original sealed containers</p>\n          <p>📅 Use within 2-3 years of purchase</p>\n          <p>🐭 Protect from rodents and moisture</p>\n          <p>📋 Keep application records</p>\n        </div>\n      `})});